export function evaluate({ inputs, time }) {
  const g = 9.8;
  const u = sdk.clamp(Number(inputs.launchSpeed), 2, 5);
  const T = 2 * u / g;
  const apexT = u / g;
  const apexH = u * u / (2 * g);
  const t = sdk.clamp(time, 0, T);
  const still = Math.abs(t - apexT) < 0.004;
  let v = u - g * t;
  if (still) v = 0;
  const h = Math.max(0, u * t - g * t * t / 2);
  const y = 350 - h * 200;
  const state = still ? 'Still for an instant' : (v > 0 ? 'Moving up' : 'Moving down');
  const objs = [];
  objs.push(...sdk.panel({ id: 'lane.toss', x: 20, y: 50, w: 600, h: 340, title: 'Tossed ball', state: 'Fixed height scale' }));
  objs.push(sdk.line('guide', 60, 350, 290, 350, { role: 'neutral' }));
  objs.push(sdk.text('guide.t', 60, 374, 'Launch height', { align: 'start' }));
  objs.push(sdk.circle('ball.toss', 320, y, 24, { role: 'output' }));
  objs.push(...sdk.vector('vec.v', { x: 370, y: y }, { value: v, direction: 'up' }, { scale: 30, label: 'v', role: 'input' }));
  objs.push(...sdk.vector('vec.a', { x: 440, y: 150 }, { value: -g, direction: 'up' }, { scale: 8, label: 'a', role: 'warning' }));
  objs.push(...sdk.callout(500, 150, [state, 'Gravity pulls down'], { id: 'callout.toss' }));
  return {
    frame: { width: 640, height: 420, objects: objs, readouts: [
      { id: 'motionState', value: state },
      { id: 'gravityState', value: 'Gravity pulls down' } ] },
    quantities: { launchSpeed: u, gravity: g, apexTime: apexT, apexHeight: apexH, velocity: v, height: h }
  };
}
